import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SCRIPTS_DIR = dirname(fileURLToPath(import.meta.url));
export const PARTS_DIR = join(SCRIPTS_DIR, "install-tools");
export const OUTPUT_FILE = join(SCRIPTS_DIR, "install-tools.sh");
const GENERATED_NOTICE =
  "# GENERATED by scripts/build-install-tools.mjs from scripts/install-tools/*.sh. Edit those files, then run: pnpm build:install-tools";

export const listParts = () =>
  readdirSync(PARTS_DIR)
    .filter((name) => name.endsWith(".sh"))
    .sort();

export function buildInstallTools() {
  const text = listParts()
    .map((name) =>
      readFileSync(join(PARTS_DIR, name), "utf8").replace(/\n+$/, ""),
    )
    .join("\n\n");
  const [shebang, ...rest] = text.split("\n");
  return `${[shebang, GENERATED_NOTICE, ...rest].join("\n")}\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(OUTPUT_FILE, buildInstallTools());
  console.log(`wrote ${OUTPUT_FILE} from ${listParts().length} parts`);
}
